effect.shader:
const vec3 W = vec3(0.2126, 0.7152, 0.0722);
float luma(vec3 c){ return dot(c, W); }
float heightAt(vec2 uv){
if (heightSource == 1) {
vec4 h = texture2DCv(heightMap.texture, uv);
return luma(h.rgb) * heightScale;
}
vec4 s = texture2DCv(inputImg.texture, uv);
return luma(s.rgb) * heightScale;
}
vec3 computeNormal(vec2 uv, vec2 texel, float radius){
float r = radius;
if (quality == 1) {
float tl = heightAt(uv + vec2(-texel.x,  texel.y) * r);
float tc = heightAt(uv + vec2( 0.0     ,  texel.y) * r);
float tr = heightAt(uv + vec2( texel.x ,  texel.y) * r);
float ml = heightAt(uv + vec2(-texel.x,  0.0    ) * r);
float mr = heightAt(uv + vec2( texel.x ,  0.0    ) * r);
float bl = heightAt(uv + vec2(-texel.x, -texel.y) * r);
float bc = heightAt(uv + vec2( 0.0     , -texel.y) * r);
float br = heightAt(uv + vec2( texel.x , -texel.y) * r);
float dx = (tr + 2.0*mr + br) - (tl + 2.0*ml + bl);
float dy = (tl + 2.0*tc + tr) - (bl + 2.0*bc + br);
return normalize(vec3(-dx * bumpIntensity, -dy * bumpIntensity, 1.0));
} else {
float hR = heightAt(uv + vec2(texel.x * r, 0.0));
float hL = heightAt(uv - vec2(texel.x * r, 0.0));
float hU = heightAt(uv + vec2(0.0, texel.y * r));
float hD = heightAt(uv - vec2(0.0, texel.y * r));
float dx = (hR - hL);
float dy = (hU - hD);
return normalize(vec3(-dx * bumpIntensity, -dy * bumpIntensity, 1.0));
}
}
float shininessFromRoughness(float r){
return mix(256.0, 8.0, clamp(r, 0.0, 1.0));
}
void main(){
vec2 uv = acScreenNorm;
vec2 texel = 1.0 / acScreenSize;
vec4 base = texture2DCv(inputImg.texture, uv);
vec4 src = base;
if (unpremultBeforeShade && src.a > 0.0) src.rgb /= src.a;
vec3 n = computeNormal(uv, texel, normalRes);
vec3 V = vec3(0.0, 0.0, 1.0);
vec3 L;
if (lightType == 1) {
vec3 lightPos = vec3(lightDir.x / 2.0, -lightDir.y / 2.0, -lightDepth * 0.02);
vec3 p = vec3(uv * 2.0 - 1.0, 0.0);
L = normalize(lightPos - p);
} else {
L = normalize(vec3(lightDir.x, -lightDir.y, lightDepth));
}
float diff = max(dot(n, L), 0.0) * lightIntensity;
vec3 H = normalize(L + V);
float specPow = shininessFromRoughness(roughness);
float spec = pow(max(dot(n, H), 0.0), specPow) * specularIntensity;
float amb = ambient;
vec3 lit = src.rgb * (amb + diff * (1.0 - amb));
lit += specularTint.rgb * spec;
lit *= exposure;
vec4 outC = vec4(lit, src.a);
if (unpremultBeforeShade && src.a > 0.0) outC.rgb *= src.a;
if (preserveAlpha) outC.a = base.a;
gl_FragColor = outC;
}
